$fpl$::jsonb) AS x(code text,playlist_id text,ord integer,confidence text,level text,match text);

DO $pre$ BEGIN
 IF (SELECT count(*) FROM _u)<>36 OR (SELECT count(DISTINCT code) FROM _u)<>36
 OR (SELECT sum(jsonb_array_length(placements)) FROM _u)<>36 OR (SELECT count(*) FROM _p)<>22 OR (SELECT count(*) FROM _pl)<>22
 OR (SELECT sum(u.ects) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'role'='mandatory'))<>165
 OR (SELECT count(*) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'group'='Opção I (CE)' AND u.ects=5))<>1
 OR (SELECT count(*) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'group'='Opção II (QAC)' AND u.ects=5))<>3
 OR (SELECT count(*) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'group'='Opção III (QAC)' AND u.ects=5))<>1
 OR EXISTS(SELECT 1 FROM _pl WHERE confidence NOT IN ('alta','média'))
 THEN RAISE EXCEPTION 'Unexpected Ciências da Educação manifest counts or ECTS (expected 165 mandatory + 5 + 5 + 5 = 180)'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR videos<4 OR language NOT IN('pt-PT','pt-BR','en'))
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id LEFT JOIN _u u ON u.code=t.code WHERE p.id IS NULL OR u.code IS NULL)
 THEN RAISE EXCEPTION 'Invalid playlist metadata or link'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.courses WHERE (code='LCEF' OR slug='ciencias-educacao-formacao'
 OR (external_source='ualg_official' AND external_id='1448')) AND id<>md5('facodi:ualg:1448:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses LCEF, the slug ciencias-educacao-formacao or UAlg 1448; reconcile manually'; END IF;
END $pre$;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
VALUES(md5('facodi:ualg:1448:course')::uuid,'course','Licenciatura em Ciências da Educação e da Formação','facodi-course-ciencias-educacao-formacao',
 'Licenciatura da Faculdade de Ciências Humanas e Sociais da Universidade do Algarve, com 180 ECTS em três anos. Filosofia, história, psicologia e sociologia da educação, investigação em educação, currículo e avaliação, educação de adultos e formação, com seminários de projeto em contextos profissionais.','[]'::jsonb,ARRAY['Ciências da Educação','Formação','Educação de adultos','Investigação em educação','Pedagogia'],ARRAY['Ciências da Educação e da Formação'],
 'pt','active',true,'import','https://www.ualg.pt/curso/1448','ualg:licenciatura:1448:course',
 jsonb_build_object('university_course_code','1448','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1448/plano',
 'source_quality','ualg_official_programme','curation_batch','facodi_ualg_1448_ciencias_educacao_formacao_20261118'))
ON CONFLICT DO NOTHING;

INSERT INTO facodi.courses(id,learning_object_id,code,external_source,external_id,slug,title,normalized_title,summary,description_html,
 degree_type,language,school,source_url,plan_url,status,published,metadata,institution,ects_total,duration_semesters)
VALUES(md5('facodi:ualg:1448:course:record')::uuid,md5('facodi:ualg:1448:course')::uuid,'LCEF','ualg_official','1448','ciencias-educacao-formacao',
 'Licenciatura em Ciências da Educação e da Formação','Ciências da Educação e da Formação','Licenciatura da Faculdade de Ciências Humanas e Sociais da Universidade do Algarve, com 180 ECTS em três anos. Filosofia, história, psicologia e sociologia da educação, investigação em educação, currículo e avaliação, educação de adultos e formação, com seminários de projeto em contextos profissionais.','<h2>Apresentação</h2><p>A licenciatura dá uma formação de banda larga, teórica, prática e metodológica, para intervir em múltiplos contextos educativos e formativos: conceber, gerir, implementar e avaliar projetos de educação e formação, formal e não formal, formar professores e formadores e fazer mediação educativa, na administração pública, em centros de formação, empresas, autarquias, associações, ONGD e serviços educativos.</p><h2>Plano de estudos</h2><p>31 unidades curriculares obrigatórias e três grupos de opção de 5 ECTS: Opção I (CE), com Educação de Infância; Opção II (QAC), com Psicologia da Motivação e Emoção, Psicologia da Personalidade e Psicologia Social; e Opção III (QAC), com Aprendizagem em Serviço. Do 2.º ano em diante, os Seminários de Projeto – Práticas Profissionais em Educação levam os estudantes a instituições de educação e formação; o último tem 15 ECTS.</p><h2>Na FACODI</h2><p>As unidades curriculares ligam a playlists abertas do YouTube, escolhidas a partir do programa da ficha oficial de cada UC.</p>',
 'Licenciatura','pt','Faculdade de Ciências Humanas e Sociais','https://www.ualg.pt/curso/1448','https://www.ualg.pt/curso/1448/plano','active',true,
 jsonb_build_object('official_course_id','1448','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1448/plano',
 'official_program_verified',true,'official_ects_total',180,'official_unit_count',36,'mandatory_unit_count',31,
 'curriculum_contains_elective_alternatives',true,'alternative_pathways_not_additive',true,
 'education_subsystem','Ensino Universitário','teaching_language','Português','shared_units_with_course',jsonb_build_object('LPSI',jsonb_build_array('14521138','14521140','14521012')),
 'source_quality','ualg_official_programme','curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1448_ciencias_educacao_formacao_20261118'),
 'Universidade do Algarve',180,6)
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
SELECT md5('facodi:ualg:1448:uc:'||u.code)::uuid,'curricular_unit',u.title,'facodi-uc-ciencias-educacao-formacao-'||u.code,u.summary,'[]'::jsonb,
 u.topics,ARRAY[u.title],'pt','active',true,'import','https://www.ualg.pt/curso/1448/plano','ualg:1448:uc:'||u.code,
 jsonb_build_object('university_course_code','1448','unit_code',u.code,'official_academic_year','2026/27',
 'official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,'study_topics',to_jsonb(u.topics),'curation_batch','facodi_ualg_1448_ciencias_educacao_formacao_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

-- Um código de UC que já seja slug de uma UC de outro curso (as três de Psicologia, na LPSI) recebe o prefixo 'ciencias-educacao-uc-' no slug.
INSERT INTO facodi.curricular_units(id,learning_object_id,course_id,code,external_source,external_id,slug,title,normalized_title,summary,
 description_html,year,semester,ects,position,language,source_url,plan_url,status,published,metadata)
SELECT md5('facodi:ualg:1448:uc:record:'||u.code)::uuid,md5('facodi:ualg:1448:uc:'||u.code)::uuid,md5('facodi:ualg:1448:course:record')::uuid,
 u.code,'ualg_official','1448:'||u.code,
 CASE WHEN EXISTS(SELECT 1 FROM facodi.curricular_units o WHERE o.slug=u.code AND o.course_id<>md5('facodi:ualg:1448:course:record')::uuid)
 THEN 'ciencias-educacao-uc-'||u.code ELSE u.code END,
 u.title,u.title,u.summary,'<p>'||u.summary||'</p><p><strong>Temas:</strong> '||array_to_string(u.topics,'; ')||'.</p>',
 u.year,u.semester,u.ects,u.position,'pt','https://www.ualg.pt/curso/1448/plano','https://www.ualg.pt/curso/1448/plano','active',true,
 jsonb_build_object('course_code','LCEF','official_course_id','1448','official_unit_code',u.code,'academic_year','2026/27',
 'official_plan_url','https://www.ualg.pt/curso/1448/plano','official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,
 'official_code_checked',true,'official_ects_checked',true,'official_semester_checked',true,
 'offered_in_both_semesters',u.offered_both_terms,'is_elective_option',u.elective_only,'official_option_group',u.option_group,
 'fuc_semester_differs_from_plan',u.fuc_semester IS NOT NULL,'official_fuc_semester',u.fuc_semester,
 'curriculum_placements',u.placements,'study_topics',to_jsonb(u.topics),'source_quality','ualg_official_structure',
 'curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1448_ciencias_educacao_formacao_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:ualg:1448:course-uc-link:'||u.code)::uuid,md5('facodi:ualg:1448:course')::uuid,md5('facodi:ualg:1448:uc:'||u.code)::uuid,
 'contains',u.position,'structured_catalog_import',
 jsonb_build_object('relation_origin','ualg_1448_official_2026_27_plan','official_code',u.code,'official_ects',u.ects,'curation_batch','facodi_ualg_1448_ciencias_educacao_formacao_20261118')
